:root {
  --ocean-deep: #0a2540;
  --ocean-mid: #1a4a7a;
  --ocean-bright: #2e86c1;
  --ocean-light: #aed6f1;
  --ocean-pale: #e8f4fd;
  --accent-teal: #17a589;
  --accent-amber: #e67e22;
  --accent-red: #c0392b;
  --text-primary: #0a2540;
  --text-muted: #5d7a96;
  --border-color: #c5dff0;
  --white: #ffffff;
  --status-green: #27ae60;
}

.permit {
  background: var(--white);
  border: 2px solid var(--ocean-mid);
  border-radius: 12px;
  width: 480px;
  overflow: hidden;
  font-size: 14px;
}

.permit-header {
  background: var(--ocean-deep);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
}

.permit-badge {
  font-size: 28px;
  line-height: 1;
}

.permit-title {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.permit-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--ocean-light);
  text-transform: uppercase;
}

.permit-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--white);
  margin: 0;
  line-height: 1.2;
}

.permit-id {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.id-label {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.1em;
  color: var(--ocean-light);
  text-transform: uppercase;
}

.id-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-teal);
}

.permit-body {
  display: flex;
  padding: 16px;
  gap: 0;
  background: var(--ocean-pale);
}

.info-col {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}

.info-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.info-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.info-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.divider {
  width: 1px;
  background: var(--border-color);
  margin: 0 16px;
  align-self: stretch;
}

.stats-col {
  display: flex;
  gap: 12px;
  align-items: center;
}

.stat-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  background: var(--white);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 10px 12px;
}

.stat-num {
  font-size: 22px;
  font-weight: 800;
  color: var(--ocean-bright);
  line-height: 1;
}

.stat-unit {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-muted);
}

.stat-desc {
  font-size: 10px;
  font-weight: 500;
  color: var(--text-primary);
  text-align: center;
}

.permit-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--white);
  border-top: 1px solid var(--border-color);
}

.zone-list {
  display: flex;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.zone {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 9px;
  border-radius: 20px;
}

.zone-open {
  background: var(--ocean-pale);
  color: var(--ocean-mid);
  border: 1px solid var(--ocean-light);
}

.zone-restricted {
  background: #fdf2f2;
  color: var(--accent-red);
  border: 1px solid #f5b7b1;
}

.permit-status {
  display: flex;
  align-items: center;
  gap: 5px;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--status-green);
}

.status-text {
  font-size: 11px;
  font-weight: 700;
  color: var(--status-green);
  letter-spacing: 0.08em;
}
